class Solution {
public:
    long long countGoodIntegers(int n, int k) {
        set<string> seen;
        int half = (n + 1) / 2;
        long long start = 1;
        for (int i = 0; i < half - 1; i++) start *= 10;
        long long end = start * 10;
        for (long long v = start; v < end; v++) {
            string s = to_string(v);
            string t = s;
            if (n % 2 == 1)
                t += string(s.rbegin() + 1, s.rend());
            else
                t += string(s.rbegin(), s.rend());
            long long val = stoll(t);
            if (val % k != 0) continue;
            sort(t.begin(), t.end());
            seen.insert(t);
        }
        long long fact[11];
        fact[0] = 1;
        for (int i = 1; i <= 10; i++) fact[i] = fact[i - 1] * i;
        long long ans = 0;
        for (const string& sig : seen) {
            int cnt[10] = {0};
            for (char c : sig) cnt[c - '0']++;
            long long total = fact[n];
            long long bad = fact[n - 1] * cnt[0];
            for (int d = 0; d < 10; d++) {
                total /= fact[cnt[d]];
                bad /= fact[cnt[d]];
            }
            ans += total - bad;
        }
        return ans;
    }
};
